CREATE FUNCTION public.revise_ai_proposal(p_id uuid,p_plan jsonb,p_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE p public.ai_action_proposals;n public.ai_action_proposals;BEGIN SELECT * INTO p FROM public.ai_action_proposals WHERE id=p_id AND user_id=p_user FOR UPDATE;IF p.id IS NULL OR p.status<>'Pending' OR p.kind<>'execution' OR p.expires_at<=now() THEN RAISE EXCEPTION 'Proposal is no longer editable';END IF;UPDATE public.ai_action_proposals SET status='Cancelled' WHERE id=p_id;INSERT INTO public.ai_action_execution_logs(proposal_id,event) VALUES(p_id,'Replaced by revision');INSERT INTO public.ai_action_proposals(conversation_id,user_id,workspace_id,project_id,business_id,kind,plan,cost) VALUES(p.conversation_id,p.user_id,p.workspace_id,p.project_id,p.business_id,p.kind,p_plan,p.cost) RETURNING * INTO n;INSERT INTO public.ai_action_execution_logs(proposal_id,event,details) VALUES(n.id,'Revised',jsonb_build_object('previous',p.id));UPDATE public.ai_messages SET parts=(SELECT jsonb_agg(CASE WHEN value->>'type'='data-proposal' AND value->'data'->>'id'=p.id::text THEN jsonb_build_object('type','data-proposal','data',to_jsonb(n)) ELSE value END) FROM jsonb_array_elements(parts)) WHERE conversation_id=p.conversation_id AND EXISTS(SELECT 1 FROM jsonb_array_elements(parts) part WHERE part->>'type'='data-proposal' AND part->'data'->>'id'=p.id::text);RETURN to_jsonb(n);END $$;REVOKE ALL ON FUNCTION public.revise_ai_proposal(uuid,jsonb,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.revise_ai_proposal(uuid,jsonb,uuid) TO service_role;